UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE (NAME LIKE 'statement/%' AND (NAME NOT LIKE 'statement/sp/%' OR NAME = 'statement/sp/stmt'))
   OR NAME IN ('wait/io/table/sql/handler', 'wait/lock/metadata/sql/mdl');
UPDATE performance_schema.setup_consumers SET ENABLED = 'YES'
WHERE NAME IN ('global_instrumentation', 'thread_instrumentation', 'statements_digest',
      'events_statements_current', 'events_statements_history');

UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME LIKE 'wait/%';
UPDATE performance_schema.setup_consumers SET ENABLED = 'YES'
WHERE NAME = 'global_instrumentation';

UPDATE performance_schema.setup_instruments SET ENABLED = 'NO', TIMED = 'NO'
WHERE NAME LIKE 'wait/synch/%' OR NAME LIKE 'wait/io/socket/%';
UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME LIKE 'wait/io/file/%'
   OR NAME IN ('wait/io/table/sql/handler', 'wait/lock/table/sql/handler', 'wait/lock/metadata/sql/mdl', 'idle', 'transaction');
UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME LIKE 'statement/%' AND (NAME NOT LIKE 'statement/sp/%' OR NAME = 'statement/sp/stmt');
UPDATE performance_schema.setup_instruments SET ENABLED = 'NO', TIMED = 'NO'
WHERE NAME LIKE 'statement/sp/%' AND NAME <> 'statement/sp/stmt';
UPDATE performance_schema.setup_instruments
   SET ENABLED = IF(FIND_IN_SET('progress', PROPERTIES), 'YES', 'NO'),
       TIMED = IF(FIND_IN_SET('progress', PROPERTIES), 'YES', 'NO')
 WHERE NAME LIKE 'stage/%';
UPDATE performance_schema.setup_instruments SET ENABLED = 'YES' WHERE NAME LIKE 'memory/%' OR NAME = 'error';
UPDATE performance_schema.setup_consumers
   SET ENABLED = IF(NAME IN ('global_instrumentation', 'thread_instrumentation', 'statements_digest', 'events_statements_current', 'events_statements_history', 'events_transactions_current', 'events_transactions_history'), 'YES', 'NO');
